// === STEP 1: guard GitHub quota on the event page, then keep only genuinely NEW stars (dedupe) ===
// "Get Recent Star Events" feeds this node one full-response item
// ({ body, headers, statusCode }), so $input.all() holds one item per page fetched.
const responses = $input.all().map((i) => i.json);
const events = [];
const remainings = [];
const messages = [];
let lastStatus = 200;
let lastRetryAfter = null;
let lastReset = null;

for (const resp of responses) {
  const status = resp.statusCode ?? resp.status ?? 200;
  const rawHeaders = resp.headers ?? {};
  const headers = {};
  for (const k of Object.keys(rawHeaders)) headers[String(k).toLowerCase()] = rawHeaders[k];
  const body = resp.body ?? resp.data;
  lastStatus = status;
  lastRetryAfter = headers['retry-after'] || lastRetryAfter;
  lastReset = headers['x-ratelimit-reset'] || lastReset;
  const remaining = Number(headers['x-ratelimit-remaining']);
  if (!Number.isNaN(remaining)) remainings.push(remaining);
  messages.push((body && body.message) || '');
  if (Array.isArray(body)) events.push(...body);
}

// Classify failures precisely: core rate limit vs. secondary (abuse) limit vs. other 403.
const message = messages.find(Boolean) || '';
const remaining = remainings.length ? Math.min(...remainings) : NaN;
const isCoreRateLimit = remaining === 0 || /rate limit/i.test(message);
const isSecondaryLimit = /abuse detection|secondary rate/i.test(message);

if (isCoreRateLimit || isSecondaryLimit) {
  throw new Error('GitHub rate limit hit while listing star events (HTTP ' + lastStatus + (isSecondaryLimit ? ' - secondary/abuse limit' : '') + '). Retry-After: ' + (lastRetryAfter || 'n/a') + 's - aborting this run; the next scheduled run retries automatically.');
}
if (lastStatus === 403 || lastStatus === 429) {
  throw new Error('GitHub returned HTTP ' + lastStatus + ' while listing star events (not a rate limit): ' + message + ' - usually a token problem.');
}
// Failsafe: stop while quota is still healthy instead of burning calls down to zero.
if (!Number.isNaN(remaining) && remaining < 20) {
  const reset = Number(lastReset) * 1000;
  throw new Error('GitHub quota nearly exhausted (x-ratelimit-remaining=' + remaining + ', resets at ' + new Date(reset).toISOString() + '). Aborting to preserve quota.');
}

// Harvest stars from the public events feed: WatchEvent (action "started") = one star.
// The /stargazers listing endpoint is now restricted to repo admins/collaborators
// (GitHub changelog 2026-06-30), but the events feed still publicly reports every star.
const stars = events
  .filter((e) => e && e.type === 'WatchEvent' && e.payload && e.payload.action === 'started' && e.actor && e.actor.login)
  .map((e) => ({ username: e.actor.login, starred_at: e.created_at }));

// One entry per (user, timestamp) pair — a re-star inside the window yields 2 events.
const seen = new Set();
const unique = stars.filter((s) => {
  const key = s.username + '|' + s.starred_at;
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});
unique.sort((a, b) => new Date(b.starred_at) - new Date(a.starred_at)); // newest first

// Manual runs = DEMO MODE: show the 10 most recent stargazers so the whole
// pipeline is demoable on demand. Editor test runs report execution mode
// "manual" (self-hosted) or "test" (n8n 2.x draft runs) - both are demo.
// Scheduled (active) runs = PRODUCTION MODE ("production"): strict dedupe
// with a watermark persisted in workflow static data.
const MODE = $execution.mode;
const isDemo = MODE === 'manual' || MODE === 'test';
const staticData = $getWorkflowStaticData('global');
const lastSeen = staticData.lastSeenStarredAt || null;

let fresh;
if (isDemo) {
  fresh = unique.slice(0, 10);
} else if (!lastSeen) {
  // First production run: set the baseline quietly instead of flooding the
  // channel with every star inside the fetched window.
  fresh = [];
} else {
  fresh = unique.filter((s) => new Date(s.starred_at) > new Date(lastSeen));
}

// Advance the watermark to the newest star we have now seen.
const newest = unique.length ? unique[0].starred_at : null;
if (newest && (!lastSeen || new Date(newest) > new Date(lastSeen))) {
  staticData.lastSeenStarredAt = newest;
}

return fresh.map((s) => ({
  json: {
    username: s.username,
    starred_at: s.starred_at,
    repo: 'n8n-io/n8n',
    demo: isDemo
  }
}));

// === STEP 2: drop failed enrichments (404 deleted users etc.), re-attach star metadata ===
const metaItems = $('Rate-Limit Guard & Dedupe').all();
const out = [];
$input.all().forEach((item, i) => {
  const profile = item.json;
  if (!profile || !profile.login) return; // enrichment failed for this star - skip it quietly
  const meta = (metaItems[i] && metaItems[i].json) || {};
  out.push({ json: { ...profile, starred_at: meta.starred_at, repo: meta.repo, demo: !!meta.demo } });
});
return out;
